flexbox-layout.code:
/* Flexbox布局示例 */
.flex-container {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 20px;
    padding: 20px;
    background-color: #f5f5f5;
    min-height: 200px;
}

.flex-item {
    background-color: #3b82f6;
    color: white;
    padding: 20px;
    border-radius: 8px;
    flex: 1;
    text-align: center;
    transition: transform 0.3s ease;
}

.flex-item:hover {
    transform: scale(1.05);
}

/* 响应式方向 */
@media (max-width: 768px) {
    .flex-container {
        flex-direction: column;
    }
}

/* HTML结构 */
/*
<div class="flex-container">
    <div class="flex-item">项目 1</div>
    <div class="flex-item">项目 2</div>
    <div class="flex-item">项目 3</div>
</div>
*/

grid-layout.code:
/* Grid布局示例 */
.grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: repeat(2, 150px);
    gap: 20px;
    padding: 20px;
    background-color: #f5f5f5;
}

.grid-item {
    background-color: #3b82f6;
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    font-size: 18px;
    font-weight: bold;
}

/* 响应式布局 */
@media (max-width: 768px) {
    .grid-container {
        grid-template-columns: 1fr;
        grid-template-rows: repeat(6, 100px);
    }
}

/* 区域命名 */
.grid-container-named {
    display: grid;
    grid-template-areas:
        "header header header"
        "sidebar main main"
        "footer footer footer";
    gap: 10px;
    min-height: 300px;
}

.header { grid-area: header; background-color: #e11d48; }
.sidebar { grid-area: sidebar; background-color: #f59e0b; }
.main { grid-area: main; background-color: #10b981; }
.footer { grid-area: footer; background-color: #8b5cf6; }

/* HTML结构 */
/*
<div class="grid-container">
    <div class="grid-item">1</div>
    <div class="grid-item">2</div>
    <div class="grid-item">3</div>
    <div class="grid-item">4</div>
    <div class="grid-item">5</div>
    <div class="grid-item">6</div>
</div>
*/

